//! Component contract shared by generated component types.
//!
//! The `#[component]` attribute turns a function's parameters into a braced
//! struct and implements this trait for that struct. Rendering a component
//! therefore consumes its typed props directly.

use crate::Element;

/// A renderable Rusty component.
///
/// Implementations are normally generated by `#[component]`. The trait is small
/// on purpose: it keeps the boundary between props and rendering explicit and
/// leaves lifecycle concerns to the reactivity milestone.
pub trait Component {
    /// Renders the component into an element tree.
    ///
    /// Components take ownership of their props. This mirrors Rust's ownership
    /// model and avoids hidden shared mutable state.
    #[must_use]
    fn render(self) -> Element;
}
